// Public review navigation points only to screens included in this deployment.
import '../immersive/object-view.js';
import '../immersive/tablet.js';
import {Storyteller,softChime} from '../immersive/narrator.js';
import {installTouchSorting,celebrate,clueRipple} from '../immersive/touch.js';
import {items,byId,allById,collections,modes,question,decision,makeQueue,sources,version} from './catalogue.js';
import {load,save,legacy,learned,mark,key} from './progress.js';
const $=id=>document.getElementById(id),root=$('main');
let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error();},setItem(){throw Error();}};}
const loaded=load(storage),data=loaded.data;
const state={view:'station',mode:'spot',collection:'all',game:null,episode:null,item:null,feedback:'',hint:false,reading:false};
let noticeTimer=0,storyOn=false,soundOn=false;
const storyteller=new Storyteller({caption:text=>{$('story-caption').textContent=text;},status:status=>{$('voice-pause').textContent=status==='paused'?'Resume':'Pause';$('voice-pause').disabled=!['paused','playing'].includes(status);$('story-bar').dataset.status=status;}});
function voiceLine(text,kind='story'){if(storyOn)storyteller.play([{text,kind}]);}
function readScene(){if(!storyOn)return;let lines=[];
 if(state.view==='station'&&state.game&&!state.game.done){const g=state.game,q=gameQuestion();lines=g.reason===q.reason?[{text:'You used the clues.',kind:'celebrate'},q.why,'Tap the next button when you are ready.']:g.chosen===q.correct?[{text:'Which clue helped you?',kind:'question'},...q.reasons.map(r=>r.text)]:[{text:`Let's explore ${allById[g.queue[g.index]].name.toLowerCase()}.`,kind:'story'},{text:q.scene,kind:'story'},{text:q.title,kind:'question'},{text:g.clues.every(Boolean)?'Slide the item token into a place, or tap a choice.':'Tap the two clue cards. Let’s see what they tell us.',kind:'clue'}];}
 else if(state.view==='episode'){const e=state.episode,it=byId[e.id],q=decision(it);lines=e.step===0?[`Meet the ${it.name.toLowerCase()}.`,it.scene,'Tap a clue. What will you discover?']:e.step===1?[{text:'What could the adult do next?',kind:'question'},q.clues[1],...q.options.map(o=>o.text)]:e.step===2?[{text:'Which clue supports the choice?',kind:'question'},...q.reasons.map(o=>o.text)]:e.step===3?[q.change.text,{text:'Would your choice change?',kind:'question'},...q.change.options.map(o=>o.text)]:[{text:'You followed the clues. A discovery to keep!',kind:'celebrate'},q.why,q.change.why];}
 else if(state.view==='station'&&state.game?.done)lines=[{text:'You found the clues!',kind:'celebrate'},'Your round is finished. Take a moment to share one thing you discovered.'];
 else lines=[root.querySelector('h1')?.textContent||'Let’s explore.',root.querySelector('.page-heading p:last-child,.episode-lead')?.textContent||'Choose an item or a short round.'];
 storyteller.play(lines);
}
function voiceOptions(){const select=$('voice-choice');const chosen=select.value;select.replaceChildren(new Option('Choose automatically',''));for(const v of storyteller.voices())select.add(new Option(v.name+' · '+v.lang,v.name));select.value=chosen;}
function enableStory(value){storyOn=value;$('listen').textContent=value?'Story voice on':'Story voice';$('listen').setAttribute('aria-pressed',String(value));$('story-bar').hidden=!value;if(value)readScene();else storyteller.stop();}
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const say=text=>{$('announce').textContent='';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('announce').textContent=text,30);};
const group=id=>collections.find(c=>c.id===id);
const visited=()=>new Set([...learned(data.records),...legacy(storage)]);
function persist(){const ok=save(storage,data);$('save-notice').hidden=ok;return ok;}
function stopReading(){storyteller.stop();}
function nav(view){location.hash='#/'+view;}
function focusMain(){root.focus({preventScroll:true});window.scrollTo?.({top:0,behavior:'instant'});}
function draw(focus=false){
 document.body.dataset.activity=state.view==='station'?(state.game?(state.game.done?'summary':'round'):'setup'):state.view;
 document.body.classList.toggle('play-screen',state.view==='episode'||state.view==='station'&&!!state.game);
 stopReading();const page={station:stationView,episodes:episodesView,episode:episodeView,book:bookView,item:itemView,about:aboutView}[state.view]||stationView;
 root.innerHTML=page();
 const active=state.view==='episode'?'episodes':state.view==='item'?'book':state.view;
 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('book-count').textContent=String(visited().size);$('reading').value=data.reading;
 document.title=({station:'Sorting Station',episodes:'Discovery episodes',episode:byId[state.episode?.id]?.name+' discovery',book:'My Discovery Book',item:byId[state.item]?.name,about:'Sources & grown-up notes'}[state.view]||'Discover')+' · FixForward';
 if(focus)focusMain();
}
function filterSelect(){return `<label class="field">Choose a collection<select id="collection"><option value="all">Mix all 10 collections</option>${collections.map(c=>`<option value="${c.id}" ${state.collection===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label>`;}
function modePicker(){return `<div class="mode-picker" role="group" aria-label="Choose a sorting game">${Object.entries(modes).map(([id,m])=>`<button data-mode="${id}" class="mode ${state.mode===id?'selected':''}" aria-pressed="${state.mode===id}"><span class="mode-symbol" aria-hidden="true">${m.icon}</span><span><strong>${m.name}</strong><small>${m.short}</small></span><span class="mode-check" aria-hidden="true">${state.mode===id?'✓':''}</span></button>`).join('')}</div>`;}
function resumeNotice(){const r=data.resume;if(!r)return '';return `<div class="resume-note"><span>You have ${r.type==='station'?'a sorting round':`a ${escape(byId[r.id].name.toLowerCase())} episode`} to continue.</span><button data-action="resume">Continue</button></div>`;}
function stationView(){
 if(state.game)return state.game.done?roundSummary():roundView();
 return `<div class="page-heading"><div><p class="eyebrow">SMALL CLUES. BIG DISCOVERIES.</p><h1>Sorting Station<span class="title-dot">.</span></h1><p>Look closely. Make a choice. Tell us why.</p></div><a class="page-chip home-link" href="#/episodes">Explore discovery episodes</a></div>${resumeNotice()}<div class="station-start"><section class="start-controls"><p class="eyebrow">CHOOSE YOUR KIND OF DISCOVERY</p>${modePicker()}<div class="start-bottom">${filterSelect()}<button class="primary start" data-action="start-round">Start a short round</button></div><p class="gentle-note">Up to 5 items. Your pace. Your discoveries.</p></section><section class="station-art"><img src="../assets/discovery-station.webp" alt="A fictional discovery station with a fan, headphones, toy robot and kettle"><div class="art-caption"><span class="caption-stamp" aria-hidden="true">✦</span><div><strong>There’s a story in every item.</strong><p>Which clue will you spot first?</p></div></div></section></div><div class="below-start"><div><span class="step-token">1</span><span><strong>Look</strong>Open the clues.</span></div><div><span class="step-token">2</span><span><strong>Choose</strong>Use what you know.</span></div><div><span class="step-token">3</span><span><strong>Discover</strong>Explain your choice.</span></div><a href="#/episodes">Explore a five-card story</a></div>`;
}
function gameQuestion(){const g=state.game;return question(allById[g.queue[g.index]],g.mode);}
function cluesMarkup(clues,opened){return `<div class="clues">${clues.map((text,i)=>`<button class="clue ${opened[i]?'opened':''}" data-clue="${i}" aria-expanded="${opened[i]}"><span class="clue-title">${opened[i]?'✓':'+'} CLUE ${i+1}</span><span>${opened[i]?escape(text):'Tap to uncover the clue'}</span></button>`).join('')}</div>`;}
function answerMarkup(options,correct,chosen,ready,type='answer'){
 return `<div class="answers ${type==='answer'?'sort-targets':''}" role="group" aria-label="${type==='reason'?'Choose the useful clue':'Choose an answer'}">${options.map((o,i)=>`<button class="answer ${chosen===o.id?'chosen':''} ${chosen===o.id&&o.id===correct?'correct':''}" data-${type}="${o.id}" ${!ready||(chosen===correct&&o.id!==chosen)?'disabled':''} ${type==='answer'?'data-drop-target="true"':''}><span class="answer-letter" aria-hidden="true">${type==='answer'?({electrical:'⚡',none:'✋',unknown:'?',reuse:'🏠',assess:'🔎',collection:'♻',keep:'♡',damage:'✋',confirmed:'✓',different:'▤',looks:'◉',size:'◇'}[o.id]||String.fromCharCode(65+i)):String.fromCharCode(65+i)}</span><span>${escape(o.text)}</span>${chosen===o.id&&o.id===correct?'<span class="answer-tick" aria-hidden="true">✓</span>':''}</button>`).join('')}</div>`;
}
function feedback(){return state.feedback?`<div class="feedback ${state.feedback.startsWith('That')?'positive':''}" role="status">${escape(state.feedback)}</div>`:'';}
function roundView(){
 const g=state.game,it=allById[g.queue[g.index]],q=gameQuestion(),ready=g.clues.every(Boolean),chosen=g.chosen===q.correct,explained=g.reason===q.reason;
 const color=group(it.collection)?.color||'mint';
 const hint=g.mode==='spot'?'Look for a clue about how the item gets power. If that information is missing, it is okay to say so.':g.mode==='plan'?'What does the adult know, and what information is still missing?':'Look for a clear statement that the service accepts this exact item.';
 const review=`<details class="clue-review"><summary>Look at the clues again</summary>${q.clues.map(c=>`<p>${escape(c)}</p>`).join('')}</details>`;
 const choice=!chosen?`${cluesMarkup(q.clues,g.clues)}<div class="choice-heading"><span class="step-tag">2</span><div><h2>Find a place that fits</h2><p>${ready?'Slide the token here, or tap a place.':'Open the two clue cards first.'}</p></div></div>${answerMarkup(q.options,q.correct,g.chosen,ready)}${feedback()}<details class="word-help hint-detail"><summary>Need a hint?</summary><p>${hint}</p></details>`:
 `<div class="reason-box ${explained?'discovery-complete':''}"><p class="eyebrow">${explained?'A DISCOVERY TO KEEP':'YOUR CHOICE FITS'}</p><h2 tabindex="-1">${explained?'You used the clues.':'Which clue helped you?'}</h2>${explained?`<div class="lesson-note"><p>${escape(q.why)}</p></div><div class="chosen-reason"><strong>Your useful clue</strong><p>${escape(q.reasons.find(r=>r.id===q.reason).text)}</p></div>${review}<button class="primary next" data-action="next-sort">${g.index===g.queue.length-1?'Finish this round':'Next item'}</button>`:`${answerMarkup(q.reasons,q.reason,g.reason,true,'reason')}${feedback()}${review}`}</div>`;
 return `<div class="round-top"><button class="quiet" data-action="pause-round">Save & leave round</button><span class="round-label">${modes[g.mode].name}</span><strong>Item ${g.index+1} of ${g.queue.length}</strong></div><div class="round-track" role="progressbar" aria-label="Items completed" aria-valuemin="0" aria-valuemax="${g.queue.length}" aria-valuenow="${g.index}">${g.queue.map((_,i)=>`<span class="${i<g.index?'done':i===g.index?'current':''}"></span>`).join('')}</div><div class="round-heading"><h1>${q.title}</h1><p>${escape(q.scene)}</p></div><div class="play-board" data-phase="${explained?'discover':chosen?'explain':'choose'}"><section class="item-side"><div class="item-ticket ${color} ${chosen?'placed':''}" draggable="false" data-ticket="${it.id}" aria-label="${escape(it.name)}. You can choose an answer with the buttons."><span class="illustrative-label">TOUCH & TURN</span><ff-object item="${it.id}" aria-label="3D ${escape(it.name)}. Slide sideways to turn it."><span class="model-fallback-icon" aria-hidden="true">${it.icon}</span></ff-object><h2>${escape(it.name)}</h2><span class="ticket-foot">Slide the model to turn it.</span><button class="grab-token" data-grab="${it.id}" ${ready&&!chosen?'':'disabled'}><span aria-hidden="true">✋</span>${chosen?'Choice made':ready?'Hold & slide me to a place':'Open both clues to move me'}</button></div>${data.reading==='detail'&&it.detail?`<details class="word-help"><summary>A little more detail</summary><p>${escape(it.detail)}</p></details>`:''}</section><section class="choice-side">${choice}</section></div>`;
}
function roundSummary(){const g=state.game;return `<div class="finish-shell"><div class="finish-emblem" aria-hidden="true">✦</div><p class="eyebrow">A GOOD PLACE TO FINISH</p><h1>You found the clues.</h1><p class="finish-intro">${g.queue.length} item${g.queue.length===1?'':'s'} explored. ${g.queue.length} choice${g.queue.length===1?'':'s'} explained.</p><div class="finished-items">${g.queue.map(id=>`<div><span aria-hidden="true">${allById[id].icon}</span><strong>${escape(allById[id].name)}</strong><small>Choice explained</small></div>`).join('')}</div><div class="finish-note"><strong>${modes[g.mode].label}</strong><p>${g.mode==='spot'?'Look for evidence of electrical power. When a clue is missing, ask for more information.':g.mode==='plan'?'The right next step depends on the information an adult has.': 'A collection service needs to confirm it accepts the exact item.'}</p></div><div class="actions"><a class="primary" href="#/book">Open my Discovery Book</a><button class="secondary" data-action="choose-round">Choose another round</button></div><details class="share-discovery"><summary>Share one discovery with a grown-up</summary><p>“One clue I noticed was… It changed my choice because…”</p><p>You can talk about a picture. There is no need to find or handle a real item.</p><a href="../#/pathway">Explore the pathway demo</a></details><p class="gentle-note">Your discoveries will be here when you return to this browser.</p></div>`;}
function collectionFilters(){return `<div class="collection-filters" role="group" aria-label="Filter learning collections"><button data-filter="all" aria-pressed="${state.collection==='all'}" class="${state.collection==='all'?'selected':''}">All items <span>20</span></button>${collections.map(c=>`<button data-filter="${c.id}" aria-pressed="${state.collection===c.id}" class="${state.collection===c.id?'selected':''}"><span aria-hidden="true">${c.icon}</span>${c.name}</button>`).join('')}</div>`;}
function episodesView(){return `<div class="page-heading"><div><p class="eyebrow">ONE ITEM. FIVE SMALL DISCOVERIES.</p><h1>Pick a story to explore<span class="title-dot">.</span></h1><p>Open clues, choose a next step, then see what changes.</p></div><span class="page-chip">No camera needed</span></div>${resumeNotice()}${collectionFilters()}<div class="catalogue">${items.filter(i=>state.collection==='all'||i.collection===state.collection).map(i=>`<a class="catalogue-card ${group(i.collection).color}" href="#/episode/${i.id}"><div class="card-top"><span class="mini-label">${escape(group(i.collection).name)}</span>${data.records[i.id]?.episode?'<span class="completed-label">✓ Explored</span>':''}</div><span class="catalogue-icon" aria-hidden="true">${i.icon}</span><h2>${escape(i.name)}</h2><p>${i.plan==='reuse'?'Another useful life':i.plan==='assess'?'Find the missing clue':i.plan==='collection'?'The right place':i.plan==='keep'?'Still part of the story':'The clue that matters'}</p><span class="card-bottom">5 cards · ${data.records[i.id]?.episode?'Revisit story':'Open story'}</span></a>`).join('')}</div><div class="small-note">Collections help you find stories. They are not recycling-bin labels. All stories are made up.</div>`;}
function episodeView(){
 const e=state.episode,it=byId[e?.id];if(!it)return episodesView();const q=decision(it),n=e.step;
 const labels=['Look','Choose','Explain','New clue','Discover'];
 let content='';
 if(n===0)content=`<p class="eyebrow">LOOK</p><h1>Meet the ${escape(it.name.toLowerCase())}.</h1><p class="episode-lead">${escape(it.scene)}</p>${cluesMarkup(q.clues,e.clues)}${data.reading==='detail'?`<div class="extra-fact"><strong>A little more detail</strong><p>${escape(it.detail)}</p></div>`:''}<button class="primary" data-action="episode-next" ${e.clues.every(Boolean)?'':'disabled'}>Choose what happens next</button>`;
 if(n===1)content=`<p class="eyebrow">CHOOSE</p><h1>What could the adult do next?</h1><p class="episode-lead">${escape(it.scene)}</p><div class="recall-clue"><strong>Your useful clue</strong><p>${escape(q.clues[1])}</p></div>${answerMarkup(q.options,q.correct,e.choice,true,'episode-answer')}${feedback()}${e.answered?'<button class="primary" data-action="episode-next">Explain the choice</button>':''}`;
 if(n===2)content=`<p class="eyebrow">EXPLAIN</p><h1>Which clue supports that choice?</h1><p class="episode-lead">A good explanation uses the information in the story.</p>${answerMarkup(q.reasons,q.reason,e.choice,true,'episode-answer')}${feedback()}${e.answered?'<button class="primary" data-action="episode-next">Discover the new clue</button>':''}`;
 if(n===3)content=`<p class="eyebrow">NEW CLUE</p><h1>Would your choice change?</h1><div class="new-clue"><span aria-hidden="true">✦</span><p>${escape(q.change.text)}</p></div>${answerMarkup(q.change.options,q.change.correct,e.choice,true,'episode-answer')}${feedback()}${e.answered?'<button class="primary" data-action="episode-next">Keep this discovery</button>':''}`;
 if(n===4)content=`<p class="eyebrow">DISCOVER · EPISODE COMPLETE</p><h1>You followed the story.</h1><div class="earned-stamp"><span aria-hidden="true">✦</span><div><strong>${escape(it.name)} discovery</strong><p>${e.fresh?'Added to your Discovery Book.':'A discovery worth revisiting.'}</p></div></div><p class="episode-lead">${escape(q.why)}</p><div class="recall-clue"><strong>When the clue changed</strong><p>${escape(q.change.why)}</p></div><div class="actions"><a class="primary" href="#/book">Open my Discovery Book</a><a class="secondary" href="#/episodes">Finish & choose a story</a></div><details class="share-discovery"><summary>Tell a grown-up what you discovered</summary><p>“First, I thought… Then the clue changed… So the adult needed to…”</p><a href="../#/pathway">Explore the pathway demo</a></details><p class="gentle-note">You can finish here. There is no next card waiting to autoplay.</p>`;
 return `<div class="round-top"><a class="quiet" href="#/episodes">${n===4?'Back to stories':'Save & leave episode'}</a><span class="round-label">${escape(it.name)}</span><strong>Card ${n+1} of 5</strong></div><ol class="episode-steps">${labels.map((label,i)=>`<li class="${i<n?'done':i===n?'current':''}" ${i===n?'aria-current="step"':''}><span>${i<n?'✓':i+1}</span>${label}</li>`).join('')}</ol><div class="episode-layout"><aside class="episode-item ${group(it.collection).color}"><p class="mini-label">A MADE-UP STORY</p><ff-object item="${it.id}" aria-label="3D ${escape(it.name)}. Slide sideways to turn it."><span class="model-fallback-icon" aria-hidden="true">${it.icon}</span></ff-object><h2>${escape(it.name)}</h2><p>${escape(it.purpose)}</p><span class="item-collection">${group(it.collection).name}</span></aside><section class="episode-content">${content}${n<4?'<p class="swipe-note">When you’re ready, tap the next button or swipe left.</p>':''}</section></div>`;
}
function bookView(){const seen=visited(),old=legacy(storage),episodes=items.filter(i=>data.records[i.id]?.episode).length;return `<div class="page-heading"><div><p class="eyebrow">YOUR DISCOVERY BOOK</p><h1>Look what you’ve learned<span class="title-dot">.</span></h1><p>Little clues you can keep, revisit and share.</p></div><div class="book-total"><strong>${seen.size}<span> / 20</span></strong><span>items explored</span></div></div><div class="book-overview"><div><span aria-hidden="true">◉</span><strong>${items.filter(i=>data.records[i.id]?.spot).length}</strong><span>electrical clues</span></div><div><span aria-hidden="true">◇</span><strong>${items.filter(i=>data.records[i.id]?.plan).length}</strong><span>next-step discoveries</span></div><div><span aria-hidden="true">▤</span><strong>${items.filter(i=>data.records[i.id]?.service).length}</strong><span>collection checks</span></div><div><span aria-hidden="true">✦</span><strong>${episodes}</strong><span>episodes completed</span></div></div>${seen.size===0?'<div class="book-welcome"><img src="../assets/discovery-station.webp" alt="Friendly items at a discovery station"><div><h2>A whole shelf of discoveries.</h2><p>Your first explained choice will appear here.</p><a class="primary" href="#/station">Try the Sorting Station</a></div></div>':''}${collectionFilters()}<div class="book-grid">${items.filter(i=>state.collection==='all'||i.collection===state.collection).map(i=>{const r=data.records[i.id]||{},earned=seen.has(i.id);return `<a href="#/item/${i.id}" class="book-card ${earned?'earned':''}"><span class="book-object" aria-hidden="true">${i.icon}</span><div><h2>${escape(i.name)}</h2><p>${r.episode?'Episode complete':earned?'A discovery to revisit':'A discovery waiting for you'}</p><div class="skill-dots" aria-label="${Object.keys(modes).filter(m=>r[m]).map(m=>modes[m].label).join(', ')||'No sorting discoveries yet'}">${Object.entries(modes).map(([m,v])=>`<span class="${r[m]?'done':''}" title="${v.label}: ${r[m]?'discovered':'not yet'}" aria-hidden="true">${r[m]?'✓':'○'}</span>`).join('')}</div>${old.includes(i.id)?'<span class="legacy-stamp">Earlier picture story ✓</span>':''}</div>${r.episode?'<span class="book-star" aria-label="Episode completed">✦</span>':''}</a>`;}).join('')}</div><p class="small-note">Your earlier picture-story stamps are included. Sorting and episode progress stays on this browser; it is not a test score or a real-world recycling total.</p>`;}
function itemView(){const it=byId[state.item];if(!it)return bookView();const r=data.records[it.id]||{};return `<div class="round-top"><a class="quiet" href="#/book">Back to my book</a><span class="round-label">${escape(group(it.collection).name)}</span></div><div class="item-detail"><div class="detail-picture ${group(it.collection).color}"><ff-object item="${it.id}" aria-label="3D ${escape(it.name)}. Slide sideways to turn it."><span class="model-fallback-icon" aria-hidden="true">${it.icon}</span></ff-object></div><section><p class="eyebrow">AN ITEM TO GET TO KNOW</p><h1>${escape(it.name)}</h1><p class="episode-lead">${escape(it.purpose)}</p><div class="recall-clue"><strong>Its electrical clue</strong><p>${escape(it.power)}</p></div><p>${escape(it.detail)}</p><div class="practice-list">${Object.entries(modes).map(([id,m])=>`<button data-practice="${it.id}:${id}"><span aria-hidden="true">${r[id]?'✓':m.icon}</span><span>${m.name}<small>${r[id]?'Revisit this discovery':'Try this discovery'}</small></span></button>`).join('')}</div><div class="actions"><a class="primary" href="#/episode/${it.id}">${r.episode?'Revisit the episode':'Explore its five-card story'}</a></div></section></div>`;}
function aboutView(){return `<div class="notes-page"><p class="eyebrow">FOR GROWN-UPS & TEACHERS</p><h1>Small stories. Clear boundaries.</h1><p class="episode-lead">20 electrical items across 10 learning collections, three sorting activities and 20 five-card episodes.</p><h2>How to use a short session</h2><ol><li>Choose one sorting round or one story.</li><li>Ask the child which clue supports the choice.</li><li>Ask what changes when new information arrives.</li><li>Finish at the summary, or choose another activity together.</li></ol><p>Use the pictures. Children do not collect, switch on, open or handle real damaged electrical items for these activities. All service names and scenarios are fictional. An image or a game answer does not assess a real item.</p><h2>Reading and access</h2><p>Short sentences is the default. More detail adds an optional fact. Story voice uses the browser’s available English voices, sentence pauses and gentle changes in pace and pitch. Voice quality and modulation depend on the device. Narration starts only after a tap and can be paused or stopped. Every drag action also has a button, and there is no time limit. The original 3D models and icons are simplified illustrations, not classification evidence. Clues reveal in response to touch. Motion is reduced when the device requests it.</p><h2>Explore the picture models</h2><p>The item pages include simplified 3D illustrations that you can turn. They are teaching pictures, not scans or evidence about real products. The separate discovery home and parts lab are not included in this review build.</p><h2>What progress means</h2><p>A sorting discovery is recorded after a correct choice and a supporting reason. An episode is recorded after the child also answers a changed situation. Revisiting never removes progress. These markers do not establish independent mastery or measure environmental impact.</p><p>Progress is saved in browser storage, without a child account, name or birth date. Earlier story stamps and adult plans stay separate when these activities are reset. No photo AI is connected to this page; the existing photo demo remains explicitly simulated.</p><h2>Content and sources</h2><p>The team-authored catalogue is based on the references below. Its ten learning collections are navigation groups, not official recycling categories. Prototype source checks are complete; educator and electrical-content review and supervised child usability testing remain pending. Version: ${version}.</p><ul class="source-list">${sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener">${s.name}</a></li>`).join('')}</ul><p>The teaching scenarios were authored for this FixForward prototype. Source organisations’ linked materials retain their own terms. The station illustration is original AI-generated story art. No external source images were copied.</p><div class="actions"><a class="primary" href="#/station">Open Sorting Station</a><a class="secondary" href="../#/about">About FixForward</a></div></div>`;}

function stationResume(){const g=state.game;if(!g||g.done)return;data.resume={type:'station',mode:g.mode,queue:[...g.queue],index:g.index};persist();}
function episodeResume(){const e=state.episode;if(!e||e.step===4)return;data.resume={type:'episode',id:e.id,step:e.step};persist();}
function startRound(queue=null,mode=state.mode){
 state.mode=mode;state.episode=null;state.game={mode,queue:queue||makeQueue(mode,state.collection,data.records,data.rounds),index:0,clues:[false,false],chosen:null,reason:null,done:false};
 state.feedback='';state.hint=false;stationResume();if(state.view!=='station')nav('station');else{draw(true);readScene();}
}
function chooseAnswer(id){const g=state.game;if(state.view!=='station'||!g||g.done||!g.clues.every(Boolean))return;const q=gameQuestion();if(!q.options.some(o=>o.id===id)||g.chosen===q.correct)return;g.chosen=id;state.feedback=id===q.correct?'That choice fits. Now find the clue that supports it.':'Try another choice. Use the information in both clues.';draw();if(id===q.correct){celebrate(root);if(soundOn)softChime('success');}voiceLine(state.feedback,id===q.correct?'celebrate':'clue');say(state.feedback);root.querySelector(id===q.correct?'.reason-box h2':`[data-answer="${id}"]`)?.focus?.();}
function nextSort(){const g=state.game;if(!g||g.done)return;const q=gameQuestion();if(g.chosen!==q.correct||g.reason!==q.reason)return;mark(data,g.queue[g.index],g.mode);g.index++;state.feedback='';state.hint=false;if(g.index>=g.queue.length){g.done=true;data.rounds++;data.resume=null;persist();}else{g.clues=[false,false];g.chosen=null;g.reason=null;stationResume();}draw(true);readScene();}
function startEpisode(id){if(!byId[id])return;state.game=null;state.episode={id,step:0,clues:[false,false],choice:null,answered:false,fresh:false};state.feedback='';episodeResume();}
function resume(){const r=data.resume;if(!r)return;if(r.type==='station'){state.mode=r.mode;state.game={...r,clues:[false,false],chosen:null,reason:null,done:false};state.episode=null;state.feedback='';if(state.view==='station')draw(true);else nav('station');}else{state.game=null;state.episode={id:r.id,step:r.step,clues:[false,false],choice:null,answered:false,fresh:false};state.feedback='';nav('episode/'+r.id);}}
function nextEpisode(){const e=state.episode;if(!e||e.step===4)return;if(e.step===0&&!e.clues.every(Boolean)||e.step>0&&!e.answered)return;e.step++;e.choice=null;e.answered=false;state.feedback='';if(e.step===4){e.fresh=mark(data,e.id,'episode');mark(data,e.id,'plan');data.resume=null;persist();}else episodeResume();draw(true);readScene();if(e.step===4){celebrate(root);if(soundOn)softChime('success');}}

document.addEventListener('click',event=>{
 const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.mode){if(!modes[b.dataset.mode])return;state.mode=b.dataset.mode;state.game=null;state.feedback='';draw();root.querySelector(`[data-mode="${state.mode}"]`)?.focus();return;}
 if(b.dataset.filter){state.collection=b.dataset.filter;draw();root.querySelector(`[data-filter="${state.collection}"]`)?.focus();return;}
 if(b.dataset.clue!==undefined){const n=Number(b.dataset.clue);if(![0,1].includes(n))return;const target=state.view==='episode'?state.episode:state.game;if(!target)return;target.clues[n]=true;draw();root.querySelector(`[data-clue="${n}"]`)?.focus();clueRipple(root,n);if(soundOn)softChime('clue');const clueText=state.view==='episode'?decision(byId[state.episode.id]).clues[n]:gameQuestion().clues[n];voiceLine(clueText,'clue');say('Clue opened.');return;}
 if(b.dataset.answer){chooseAnswer(b.dataset.answer);return;}
 if(b.dataset.reason){const g=state.game;if(!g||g.done)return;const q=gameQuestion();if(g.chosen!==q.correct||g.reason===q.reason||!q.reasons.some(r=>r.id===b.dataset.reason))return;g.reason=b.dataset.reason;state.feedback=g.reason===q.reason?'That explanation uses the clue.':'Try another reason. What did the story actually tell you?';draw();root.querySelector(g.reason===q.reason?'[data-action="next-sort"]':`[data-reason="${g.reason}"]`)?.focus();say(state.feedback);voiceLine(state.feedback,state.feedback.startsWith('That')?'celebrate':'clue');return;}
 if(b.dataset.episodeAnswer){const e=state.episode;if(!e||e.answered||![1,2,3].includes(e.step))return;const q=decision(byId[e.id]),correct=e.step===1?q.correct:e.step===2?q.reason:q.change.correct,choices=e.step===1?q.options:e.step===2?q.reasons:q.change.options;if(!choices.some(o=>o.id===b.dataset.episodeAnswer))return;e.choice=b.dataset.episodeAnswer;e.answered=e.choice===correct;state.feedback=e.answered?'That choice fits the information.':'Try again. Think about the clue in this story.';draw();root.querySelector(`[data-episode-answer="${e.choice}"]`)?.focus();say(state.feedback);voiceLine(state.feedback,state.feedback.startsWith('That')?'celebrate':'clue');return;}
 if(b.dataset.practice){const [id,mode]=b.dataset.practice.split(':');if(byId[id]&&modes[mode])startRound([id],mode);return;}
 switch(b.dataset.action){case 'start-round':startRound();break;case 'resume':resume();break;case 'next-sort':nextSort();break;case 'choose-round':state.game=null;state.feedback='';draw(true);break;case 'pause-round':stationResume();state.game=null;state.feedback='';draw(true);break;case 'hint':state.hint=true;draw();root.querySelector('.hint')?.focus();say('Hint opened.');break;case 'episode-next':nextEpisode();break;}
});
document.addEventListener('change',event=>{if(event.target.id==='collection')state.collection=event.target.value;});
$('reading').onchange=()=>{data.reading=$('reading').value==='detail'?'detail':'short';persist();draw();$('reading').focus();};
$('listen').onclick=()=>enableStory(!storyOn);
$('voice-pause').onclick=()=>storyteller.paused?storyteller.resume():storyteller.pause();
$('voice-repeat').onclick=readScene;$('voice-stop').onclick=()=>enableStory(false);
$('voice-choice').onchange=e=>{storyteller.voiceName=e.target.value;readScene();};
$('voice-pace').onchange=e=>{storyteller.rate=Number(e.target.value);readScene();};
$('sound-effects').onclick=()=>{soundOn=!soundOn;$('sound-effects').setAttribute('aria-pressed',String(soundOn));$('sound-effects').textContent=soundOn?'Sounds on':'Sounds off';if(soundOn)softChime();};
voiceOptions();if('speechSynthesis'in window)window.speechSynthesis.addEventListener?.('voiceschanged',voiceOptions);
installTouchSorting(root,{onDrop:(answer,id)=>{if(state.game?.queue[state.game.index]===id)chooseAnswer(answer);},onPickup:()=>{if(soundOn)softChime();}});
let swipe=null;root.addEventListener('pointerdown',e=>{if(state.view==='episode'&&!e.target.closest('button,a,select,ff-object,input,summary'))swipe={x:e.clientX,y:e.clientY};});root.addEventListener('pointerup',e=>{if(swipe&&state.view==='episode'&&swipe.x-e.clientX>95&&Math.abs(swipe.y-e.clientY)<55)nextEpisode();swipe=null;});root.addEventListener('pointercancel',()=>swipe=null);
document.addEventListener('dragstart',event=>{const ticket=event.target.closest('[data-ticket]');if(!ticket)return;if(ticket.draggable!==true){event.preventDefault();return;}event.dataTransfer.setData('text/plain',ticket.dataset.ticket);event.dataTransfer.effectAllowed='move';ticket.classList.add('dragging');});
document.addEventListener('dragend',()=>document.querySelectorAll('.dragging,.drag-over').forEach(el=>el.classList.remove('dragging','drag-over')));
document.addEventListener('dragover',event=>{const target=event.target.closest('[data-drop-target]');if(target&&!target.disabled){event.preventDefault();target.classList.add('drag-over');}});
document.addEventListener('dragleave',event=>event.target.closest('[data-drop-target]')?.classList.remove('drag-over'));
document.addEventListener('drop',event=>{const target=event.target.closest('[data-answer]');if(!target||target.disabled||!state.game)return;event.preventDefault();target.classList.remove('drag-over');if(event.dataTransfer.getData('text/plain')===state.game.queue[state.game.index])chooseAnswer(target.dataset.answer);});
$('reset-progress').onclick=()=>{const d=$('reset-dialog');if(typeof d.showModal==='function')d.showModal();else if(window.confirm('Clear sorting and episode progress on this browser? Earlier picture stories and adult plans stay saved.'))clearProgress();};
function clearProgress(){try{storage.removeItem(key);}catch{}const fresh=load({getItem:()=>null}).data;Object.keys(data).forEach(k=>delete data[k]);Object.assign(data,fresh);state.game=null;state.episode=null;state.feedback='';state.collection='all';persist();if(state.view==='station')draw(true);else nav('station');say('Sorting and episode progress cleared.');}
$('reset-dialog').addEventListener('close',()=>{if($('reset-dialog').returnValue==='clear')clearProgress();});
function route(){const [view,id]=location.hash.replace(/^#\//,'').split('/');state.feedback='';state.hint=false;
 if(view==='episode'&&byId[id]){state.view='episode';if(state.episode?.id!==id||state.episode.step===4)startEpisode(id);}
 else if(view==='item'&&byId[id]){state.view='item';state.item=id;}
 else state.view=['station','episodes','book','about'].includes(view)?view:'station';
 draw(true);readScene();
}
window.addEventListener('hashchange',route);window.addEventListener('pagehide',()=>{stopReading();clearTimeout(noticeTimer);});
window.addEventListener('storage',event=>{if(event.key==='fixforward-i3-site-v2'){$('book-count').textContent=String(visited().size);if(state.view==='book')draw();}});
$('save-notice').hidden=loaded.available;route();
